from gurobipy import gp, Model, GRB

# Create model
model = gp.Model()

# Define sets
cities = ["A", "B"]
links = [["A", "B"]]
products = ["Product1"]

# Define parameters from input
supply = {"A": 10, "B": 0}
demand = {"A": 0, "B": 10}
shipment_cost = {"A": {"B": 1}}
capacity = {"A": {"B": 10}}
joint_capacity = {"A": {"B": 10}}

# Decision variables: amount of product p shipped from city i to city j
x = model.addVars(
    [(i, j) for i in cities for j in cities],
    lb=0,
    name="shipment"
)

# Objective: minimize total shipping cost
model.setObjective(
    gp.quicksum(shipment_cost[i][j] * x[i, j] 
                for i in cities for j in cities),
    GRB.MINIMIZE
)

# Supply constraints: total shipped from city i <= supply at city i
for i in cities:
    model.addConstr(
        gp.quicksum(x[i, j] for j in cities) <= supply[i],
        name=f"supply_{i}"
    )

# Demand constraints: total received at city j >= demand at city j
for j in cities:
    model.addConstr(
        gp.quicksum(x[i, j] for i in cities) >= demand[j],
        name=f"demand_{j}"
    )

# Joint capacity constraints: total shipped on link (i, j) <= joint capacity
for (i, j) in links:
    model.addConstr(
        gp.quicksum(x[i, j] for p in products) <= joint_capacity[i][j],
        name=f"joint_capacity_{i}_{j}"
    )

# Product capacity constraints: shipped amount on link (i, j) for product p <= capacity
for (i, j) in links:
    for p in products:
        model.addConstr(
            x[i, j] <= capacity[i][j],
            name=f"capacity_{i}_{j}_{p}"
        )

# Optimize
model.optimize()

# Print final objective
print(f"FINAL_OBJECTIVE={model.objVal}")
