import gurobipy as gp
from gurobipy import GRB

model = gp.Model(env=env)

# Create decision variables
# x[i][j] = 1 if participant i is assigned to car j, 0 otherwise
participants = ["P1", "P2", "P3"]
cars = ["C1", "C2", "C3"]
possible_assignments = [[1, 0, 1], [0, 1, 0], [1, 1, 1]]

# Create binary variables for each participant-car pair
x = {}
for i, p in enumerate(participants):
    for j, c in enumerate(cars):
        x[(p, c)] = model.addVar(vtype=GRB.BINARY, name=f"x_{p}_{c}")

# Constraint: can only assign if participant is interested in the car
for i, p in enumerate(participants):
    for j, c in enumerate(cars):
        if possible_assignments[i][j] == 0:
            model.addConstr(x[(p, c)] == 0, name=f"interest_{p}_{c}")

# Constraint: each participant assigned to at most one car
for i, p in enumerate(participants):
    model.addConstr(gp.quicksum(x[(p, c)] for c in cars) <= 1, name=f"participant_{p}")

# Constraint: each car accommodates at most one participant
for j, c in enumerate(cars):
    model.addConstr(gp.quicksum(x[(p, c)] for p in participants) <= 1, name=f"car_{c}")

# Objective: maximize total assignments
model.setObjective(gp.quicksum(x[(p, c)] for p in participants for c in cars), GRB.MAXIMIZE)

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
